Object.assign(window.deepArticles,{
  "east-indies-successor-states":southernArchipelagoArticle({
    title:"Southern Archipelago States",category:"Regional systems",eyebrow:"Fifteen-state successor order · 1947–present",infoboxKicker:"Former Dutch East Indies",
    flag:{src:"assets/diagrams/southern-archipelago-states.svg",alt:"Schematic of the fifteen Southern Archipelago states",caption:"The mature system contains fifteen sovereign associated states; the Bornean State replaced Bornean Malaya after the 1970s war"},
    lead:"The Southern Archipelago States are the fifteen sovereign countries created from the former Dutch East Indies and adjacent Bornean territories under the Japanese victory settlement. Official usage rejects Indonesia as the name of a natural country: Java, Sumatra, Borneo, Sulawesi, Bali, and the eastern islands are organized as separate states joined by technical councils, Japanese strategy, Singaporean finance, and corporate ownership.",
    canon:"The fifteen-state principle, named state map, separate Papuan settlement, pre-sovereignty corporate asset capture, suppression of a united Indonesian government, and Southern Archipelago Council are established. Several formal titles, flags, constitutions, borders, and post-2000 arrangements remain open.",
    sections:[
      {id:"settlement",title:"From occupation zones to permanent states",html:"<p>The <a href='japanese-east-indies.html'>Japanese East Indies administration</a> never creates one seamless archipelagic government. Sumatra, Java and Madura, and the naval eastern zone become foundations for a settlement in which cultural distinction, island geography, inherited institutions, and economic viability determine statehood.</p>"},
      {id:"fifteen",title:"The fifteen-state system",html:"<p>Java contains <a href='sunda.html'>Sunda</a>, <a href='mataram.html'>Mataram</a>, and <a href='east-java-madura.html'>East Java and Madura</a>. Sumatra contains <a href='aceh.html'>Aceh</a>, <a href='tapanuli.html'>Tapanuli</a>, <a href='minangkabau.html'>Minangkabau</a>, and the <a href='sumatran-malay-federation.html'>Sumatran Malay Federation</a>.</p><p>Borneo contains the <a href='bornean-state.html'>Bornean State</a> and <a href='kalimantan-federation.html'>Kalimantan Federation</a>; Sulawesi contains <a href='south-sulawesi.html'>South</a> and <a href='north-sulawesi.html'>North Sulawesi</a>; the eastern group contains <a href='bali.html'>Bali</a>, <a href='lombok-sumbawa.html'>Lombok–Sumbawa</a>, the <a href='eastern-lesser-sunda-federation.html'>Eastern Lesser Sunda Federation</a>, and the <a href='moluccan-federation.html'>Moluccan Federation</a>.</p>"},
      {id:"borneo",title:"The Bornean replacement",html:"<p><a href='bornean-malaya.html'>Bornean Malaya</a> is one of the original fifteen governments. The Malay–Bornean War and triangular settlement replace it with a Bornean national state by 1979. The count therefore remains fifteen while one member changes constitutional identity.</p>"},
      {id:"corporate",title:"Sovereignty after asset capture",html:"<p>Japanese firms take custody of Dutch and other European plantations, oil, mines, banks, ports, shipping, railways, and utilities before the associated states receive recognition. Independence treaties preserve concessions, debt, management contracts, and Japanese technical standards.</p><p>The governments own territory and citizenship; Japanese houses own or operate much of the economy that makes government solvent.</p>"},
      {id:"indonesia",title:"Indonesia as an opposition idea",html:"<p>The <a href='indonesian-unification-movement.html'>Indonesian unification movement</a> survives in exile, cultural associations, ports, student circles, and opposition politics. Officials describe Indonesia as a Javanese centralist project that would erase smaller nations; unificationists describe the state system as the country Japan prevented from being born.</p>"},
      {id:"council",title:"Common machinery without federation",html:"<p>The <a href='southern-archipelago-council.html'>Southern Archipelago Council</a> coordinates shipping, customs forms, disease control, weather, fisheries, radio, postal standards, labor movement, piracy, and rescue. It has no citizenship, army, taxing power, parliament, or independent foreign policy.</p>"},
      {id:"contests",title:"Sovereignty contests, 1970–1985",html:"<p>National governments demand royalties, taxation, local hiring, development banks, port participation, and shorter concessions. Corporate groups redirect shipping, credit, insurance, and investment among competing states, teaching each cabinet the cost of becoming the difficult government.</p>"},
      {id:"position",title:"The system by 1985",html:"<p>The states possess real laws, rulers, police, schools, and political communities. None can negotiate as a single archipelagic bloc. This combination of genuine sovereignty and competitive dependence makes the southern islands the earliest laboratory of Japanese corporate political power.</p>"}
    ],
    related:[{href:"southern-archipelago-council.html",kicker:"Common institution",label:"Southern Archipelago Council"},{href:"japanese-east-indies.html",kicker:"Administrative predecessor",label:"Japanese East Indies"},{href:"indonesian-unification-movement.html",kicker:"Suppressed alternative",label:"Indonesian Unification Movement"},{href:"japan.html",kicker:"Strategic hegemon",label:"Empire of Japan"}],
    facts:[["Predecessor","Dutch East Indies and British Bornean possessions"],["Initial recognition","1947–1955"],["Mature member states","Fifteen"],["Collective official name","Southern Archipelago States"],["Unified Indonesia","Absent"],["Common body","Southern Archipelago Council"],["Financial center","Singapore"],["Economic order","Sovereignty beneath Japanese corporate primacy"]]
  }),

  "sunda":southernArchipelagoArticle({
    title:"Sunda",infoboxKicker:"Western Javanese associated state",flag:{src:"assets/diagrams/java-three-state-balance.svg",alt:"Java's three-state balance",caption:"Sunda holds western Java and Batavia, but not the Javanese courts or Surabaya"},
    lead:"Sunda is the Sundanese-speaking associated state of western Java and Banten. Its government sits at Bandung while Batavia remains a specially chartered commercial port dominated by Japanese and international banks, shipping, insurers, and trading houses.",
    canon:"Western Java and Banten, Bandung as capital, Batavia inside Sundanese sovereignty under a commercial charter, and the state's economic profile are established. Formal constitutional title, flag, leadership, and charter text remain open.",
    sections:[
      {id:"formation",title:"Formation from western Java",html:"<p>Japan separates the Sundanese-speaking west from central and eastern Java to prevent any Javanese government from inheriting the whole colonial administrative center. Regional institutions, language, and Bandung's modern bureaucracy supply the new state with a plausible national core.</p>"},
      {id:"territory",title:"Western Java and Banten",html:"<p>The state extends across the western third of Java and Banten. Its population and agricultural base are large enough for independence, while the three-state settlement denies it the courts of Yogyakarta and Surakarta and the eastern naval-industrial system.</p>"},
      {id:"capital",title:"Bandung and Batavia",html:"<p>Bandung is the administrative capital and center of national education, government, and Sundanese public life. Batavia remains the principal port and an international corporate city whose charter limits the national government's direct commercial control.</p>"},
      {id:"economy",title:"Plantations, textiles, and assembly",html:"<p>Tea, food, plantations, textiles, light manufacturing, and later consumer-goods assembly join the western hinterland to Batavian finance and shipping. Japanese houses control many high-value import, banking, and port relationships.</p>"},
      {id:"language",title:"Sundanese national culture",html:"<p>Sundanese is the language of national education, regional broadcasting, and public culture. Malay remains useful in trade; Japanese dominates advanced technical, banking, and inter-Sphere administration.</p>"},
      {id:"charter",title:"The Batavian charter dispute",html:"<p>Governments repeatedly seek greater customs revenue, local management, housing authority, and policing power in the port district. Corporate interests defend the charter as the condition that makes Batavia the archipelago's western commercial gateway.</p>"},
      {id:"java",title:"Relations with the other Javanese states",html:"<p>Sunda competes with Mataram for cultural influence and East Java for shipping and industry. Technical agreements make Java function as one market without giving any member authority to reunify the island.</p>"},
      {id:"position",title:"Position by 1985",html:"<p>Sunda is one of the southern system's more diversified and politically capable states. Its central contradiction remains the separation between a national capital at Bandung and a port economy whose most powerful institutions answer abroad.</p>"}
    ],related:[{href:"mataram.html",kicker:"Central Javanese neighbor",label:"Mataram"},{href:"east-java-madura.html",kicker:"Eastern Javanese neighbor",label:"East Java and Madura"},{href:"southern-archipelago-council.html",kicker:"Common institution",label:"Southern Archipelago Council"},{href:"indonesian-unification-movement.html",kicker:"Political alternative",label:"Indonesian Unification Movement"}],facts:[["Capital","Bandung"],["Principal port","Batavia"],["Territory","Western Java and Banten"],["Major language","Sundanese"],["Political form","Associated sovereign state"],["Port status","Special commercial charter"],["Economic strengths","Plantations, textiles, food, and light industry"],["1985 alignment","GEACPS"]]
  }),

  "mataram":southernArchipelagoArticle({
    title:"Mataram",infoboxKicker:"Central Javanese court federation",flag:{src:"assets/diagrams/java-three-state-balance.svg",alt:"Java's three-state balance",caption:"Mataram possesses Java's royal and cultural center but no commanding international seaport"},
    lead:"Mataram is the central Javanese court federation organized around Yogyakarta and Surakarta. It holds the strongest concentration of Javanese royal, scholarly, religious, and classical cultural authority while the victory settlement denies it Batavia and Surabaya.",canon:"The central Javanese territory, dual court structure, Yogyakarta's administrative primacy, Surakarta's ceremonial role, and deliberate port limitation are established. Federal crown arrangements and officeholders remain open.",
    sections:[
      {id:"foundation",title:"A federation of surviving courts",html:"<p>Japanese planners restore and federate the central Javanese houses rather than create a unitary republic. The arrangement converts inherited prestige into government while ensuring that no single court can speak for all Java.</p>"},
      {id:"centers",title:"Yogyakarta and Surakarta",html:"<p>Yogyakarta serves as the principal administrative capital. Surakarta retains a second court and ceremonial position, producing a dual institutional culture of ministries, royal households, universities, and learned societies.</p>"},
      {id:"rural",title:"Rice, sugar, and the rural majority",html:"<p>Rice districts, sugar, crafts, local markets, and a very large rural population anchor the economy. Land, irrigation, tenancy, religious schools, and village administration remain central political questions.</p>"},
      {id:"culture",title:"Classical Javanese authority",html:"<p>The courts, language, literature, performance, religion, and universities give Mataram influence beyond its borders. Other Javanese governments resist any claim that this cultural preeminence creates political seniority.</p>"},
      {id:"ports",title:"The port limitation",html:"<p>Mataram does not control Batavia or Surabaya. Rail and road agreements guarantee access, but customs, naval industry, and the principal international shipping systems remain under neighboring jurisdictions.</p>"},
      {id:"japan",title:"Japanese relationship",html:"<p>Tokyo presents itself as protector of the courts and classical civilization. Japanese banks and firms finance transport and agricultural modernization while avoiding the concentration of heavy industry that could make Mataram the nucleus of reunification.</p>"},
      {id:"politics",title:"Court, ministry, and popular politics",html:"<p>Royal authority coexists with ministers, councils, religious networks, universities, cooperatives, and rural political organizations. Debate concerns how much inherited hierarchy can guide a modern sovereign state.</p>"},
      {id:"position",title:"Position by 1985",html:"<p>Mataram is culturally formidable and commercially constrained. Its leaders can shape Javanese thought more readily than they can command the island's ports, factories, or inter-Sphere credit.</p>"}
    ],related:[{href:"sunda.html",kicker:"Western neighbor",label:"Sunda"},{href:"east-java-madura.html",kicker:"Eastern neighbor",label:"East Java and Madura"},{href:"indonesian-unification-movement.html",kicker:"Contested national idea",label:"Indonesian Unification Movement"},{href:"southern-archipelago-council.html",kicker:"Common machinery",label:"Southern Archipelago Council"}],facts:[["Administrative capital","Yogyakarta"],["Second royal center","Surakarta"],["Territory","Central Java"],["Government","Court federation"],["Economic base","Rice, sugar, crafts, and education"],["International seaport","None under direct control"],["Cultural position","Principal classical Javanese center"],["1985 alignment","GEACPS"]]
  }),

  "east-java-madura":southernArchipelagoArticle({
    title:"East Java and Madura",infoboxKicker:"Maritime-industrial Javanese state",flag:{src:"assets/diagrams/java-three-state-balance.svg",alt:"Java's three-state balance",caption:"Surabaya makes East Java and Madura the maritime and industrial pole of divided Java"},
    lead:"East Java and Madura is the maritime and industrial Javanese state centered on Surabaya. It joins eastern Java's manufacturing, rail, sugar, tobacco, ship repair, and naval facilities to an internally autonomous Madurese island.",canon:"Eastern Java, Madura, Surabaya, Madurese autonomy, and the maritime-industrial role are established. The formal title, constitutional balance, flag, and armed-service structure remain open.",
    sections:[
      {id:"formation",title:"The eastern Javanese settlement",html:"<p>Japan separates Surabaya and its hinterland from the central courts to deny Mataram control of the island's principal eastern port. Municipal, commercial, military, and labor institutions give the new state a less court-centered identity.</p>"},
      {id:"surabaya",title:"Surabaya",html:"<p>Surabaya is capital, port, railway center, naval station, and industrial metropolis. Its yards and workshops connect Java to Bali, Sulawesi, the Moluccas, and the Lesser Sundas.</p>"},
      {id:"madura",title:"Madura's autonomy",html:"<p>Madura retains its own councils, local authorities, cultural institutions, and administrative guarantees. The bargain prevents the union from becoming an ordinary East Javanese province system.</p>"},
      {id:"economy",title:"Industry and export agriculture",html:"<p>Ship repair, rail workshops, manufacturing, sugar, tobacco, food processing, and eastern-island commerce produce a diversified base. Japanese firms are especially prominent in shipping, machinery, and naval supply.</p>"},
      {id:"military",title:"Maritime and military role",html:"<p>The state supplies ports, crews, repair, patrol craft, and logistics to the southern sea lanes. Japan retains strategic access and limits independent heavy armament while relying on local police and maritime services.</p>"},
      {id:"labor",title:"Municipal and labor politics",html:"<p>Dockworkers, railway employees, factory labor, merchants, military families, and municipal officials make politics more urban and organizational than in Mataram. Industrial disputes often become tests of Japanese corporate privilege.</p>"},
      {id:"java",title:"The three-way balance",html:"<p>East Java needs central Javanese food and labor and western Javanese finance and markets. It nevertheless resists cultural or political leadership from either neighbor and treats Surabaya's eastern orientation as a national advantage.</p>"},
      {id:"position",title:"Position by 1985",html:"<p>The country is Java's principal maritime-industrial state and the southern council's eastern gateway. Its leverage is substantial but insufficient to reunify the island without provoking Japan and both Javanese neighbors.</p>"}
    ],related:[{href:"sunda.html",kicker:"Western Javanese state",label:"Sunda"},{href:"mataram.html",kicker:"Central Javanese state",label:"Mataram"},{href:"south-sulawesi.html",kicker:"Maritime partner",label:"South Sulawesi"},{href:"japanese-east-indies.html",kicker:"Administrative predecessor",label:"Japanese East Indies"}],facts:[["Capital","Surabaya"],["Territory","Eastern Java and Madura"],["Internal autonomy","Madura"],["Political form","Associated sovereign state"],["Economic strengths","Shipping, rail, sugar, tobacco, and manufacturing"],["Strategic role","Eastern Javanese naval and industrial center"],["Principal external power","Japan"],["1985 alignment","GEACPS"]]
  }),

  "aceh":southernArchipelagoArticle({
    title:"Sultanate of Aceh",infoboxKicker:"Northern Sumatran Islamic monarchy",flag:{src:"assets/diagrams/sumatran-four-state-system.svg",alt:"Sumatra's four-state system",caption:"Aceh combines an old sovereign tradition with oil and control of the western Malacca approach"},
    lead:"The Sultanate of Aceh is the restored Islamic state of northern Sumatra. Its history of independent sovereignty, religious scholarship, armed resistance, oil, plantations, and position at the western approach to the Strait of Malacca give it unusual bargaining power within the Southern Archipelago system.",canon:"The northern Sumatran territory, reconstituted sultanate, capital at Kutaraja, Islamic political character, and stronger concession bargaining are established. Dynasty, succession, flag, and exact concession map remain open.",
    sections:[
      {id:"restoration",title:"Restoration of sovereignty",html:"<p>Japan uses the memory and institutions of the precolonial sultanate to separate Aceh from both Batak territories and a Malay-led Sumatran state. Independence is presented as the reversal of Dutch conquest rather than the invention of a client polity.</p>"},
      {id:"government",title:"Sultan, ulema, and ministries",html:"<p>The restored court governs beside ulema, military patrons, merchants, regional notables, and modern ministries. Religious legitimacy gives the government a constituency that Japanese corporate institutions cannot easily replace.</p>"},
      {id:"economy",title:"Oil and plantations",html:"<p>Oil, plantations, ports, fisheries, and Malacca-route services give Aceh revenue beyond ordinary agriculture. Japanese concessions remain important, but the state can demand higher royalties and local employment more credibly than poorer island governments.</p>"},
      {id:"strait",title:"The western Malacca approach",html:"<p>Aceh's position matters to shipping entering the Strait of Malacca from the Indian Ocean. Maritime surveillance, pilotage, rescue, and Japanese security arrangements give a relatively small state wider strategic weight.</p>"},
      {id:"society",title:"Islamic national society",html:"<p>Schools, mosques, courts, charitable foundations, and military memory support a distinctive national public. Malay functions in regional trade while Acehnese and Islamic scholarship anchor domestic identity.</p>"},
      {id:"japan",title:"A negotiated Japanese relationship",html:"<p>Tokyo works through the sultanate and religious authorities rather than attempting direct cultural administration. Disputes concern concession law, military access, and the limits of corporate conduct rather than Aceh's formal right to exist.</p>"},
      {id:"sumatra",title:"Relations across Sumatra",html:"<p>Aceh trades with Tapanuli and the Sumatran Malay Federation while resisting any organization that could subordinate it to Medan, Palembang, or a pan-Indonesian center.</p>"},
      {id:"position",title:"Position by 1985",html:"<p>Aceh is the strongest Islamic sovereign voice among the southern states. It remains inside Japan's strategic order but is one of the members most capable of making corporate entry conditional.</p>"}
    ],related:[{href:"tapanuli.html",kicker:"Southern neighbor",label:"Tapanuli"},{href:"sumatran-malay-federation.html",kicker:"Commercial neighbor",label:"Sumatran Malay Federation"},{href:"singapore.html",kicker:"Strait clearing center",label:"Singapore"},{href:"southern-archipelago-council.html",kicker:"Regional institution",label:"Southern Archipelago Council"}],facts:[["Capital","Kutaraja"],["Territory","Northern Sumatra"],["Government","Reconstituted sultanate"],["Religious character","Islamic"],["Economic strengths","Oil, plantations, and maritime services"],["Strategic position","Western approach to the Strait of Malacca"],["Corporate dependence","Substantial but comparatively negotiable"],["1985 alignment","GEACPS"]]
  }),

  "tapanuli":southernArchipelagoArticle({
    title:"Tapanuli",infoboxKicker:"Batak federal associated state",flag:{src:"assets/diagrams/sumatran-four-state-system.svg",alt:"Sumatra's four-state system",caption:"Tapanuli protects the Batak highlands from incorporation into Aceh or a Malay-led federation"},
    lead:"Tapanuli is the federal state of the Batak highlands and the western north-Sumatran coast. Regional councils reconcile Christian and Muslim Batak communities, customary clan institutions, plantations, and a modern administration without placing the interior under Acehnese or Malay rule.",canon:"The Batak-centered federal state, regional-council structure, exclusion of Medan, internal religious plurality, and general economic basis are established. Capital, formal title, flag, and council apportionment remain open.",
    sections:[
      {id:"formation",title:"A state against external incorporation",html:"<p>Tapanuli is created because neither Acehnese nor lowland Malay sovereignty can plausibly absorb the Batak highlands. Japan consolidates several related but distinct districts into a federation rather than creating many mountain microstates.</p>"},
      {id:"federal",title:"Regional councils and customary government",html:"<p>Local councils, clan institutions, churches, Muslim authorities, and modern departments share power. The federal structure protects community life while providing the roads, taxation, courts, and police required of a sovereign state.</p>"},
      {id:"religion",title:"Christian and Muslim communities",html:"<p>Mission-era Christian institutions give several districts strong schools and professional networks. Muslim Batak communities and customary systems prevent Christianity from defining the whole federation.</p>"},
      {id:"capital",title:"The unsettled capital question",html:"<p>Pematangsiantar, Tarutung, and a purpose-built administrative center remain plausible national seats. Medan lies outside the federation in the Sumatran Malay commercial system.</p>"},
      {id:"economy",title:"Highlands, plantations, and education",html:"<p>Agriculture, plantations, forest products, roads, schools, and skilled migration sustain the country. Its human capital is more significant than its command of oil, ports, or heavy industry.</p>"},
      {id:"corporate",title:"Japanese technical networks",html:"<p>Japanese firms and inherited mission schools supply engineers, teachers, medical staff, and transport projects. Federal authorities seek outside skill without surrendering local education or land administration.</p>"},
      {id:"neighbors",title:"Relations with Aceh and the Malay lowlands",html:"<p>Boundary, labor, road, and plantation questions recur with Aceh and the Sumatran Malay Federation. Tapanuli's existence blocks either neighbor from claiming all northern Sumatra.</p>"},
      {id:"position",title:"Position by 1985",html:"<p>Tapanuli is administratively capable but economically secondary. Its success is measured less by regional power than by preservation of Batak self-government inside a Japanese-centered economy.</p>"}
    ],related:[{href:"aceh.html",kicker:"Northern neighbor",label:"Sultanate of Aceh"},{href:"sumatran-malay-federation.html",kicker:"Eastern neighbor",label:"Sumatran Malay Federation"},{href:"minangkabau.html",kicker:"Southern cultural neighbor",label:"Minangkabau"},{href:"southern-archipelago-council.html",kicker:"Regional institution",label:"Southern Archipelago Council"}],facts:[["Capital","Open; Pematangsiantar or Tarutung commonly proposed"],["Territory","Batak highlands and western north-Sumatran coast"],["Government","Federal regional-council state"],["Principal peoples","Batak communities"],["Religious order","Christian, Muslim, and customary pluralism"],["Medan","Outside the state"],["Economic strengths","Agriculture, plantations, education, and skilled labor"],["1985 alignment","GEACPS"]]
  }),

  "minangkabau":southernArchipelagoArticle({
    title:"Minangkabau",infoboxKicker:"West Sumatran customary state",flag:{src:"assets/diagrams/sumatran-four-state-system.svg",alt:"Sumatra's four-state system",caption:"Minangkabau reconciles Islamic public life, matrilineal custom, revived monarchy, and merchant networks"},
    lead:"Minangkabau is the west Sumatran state centered on Bukittinggi and the port of Padang. Its constitutional order combines Islamic institutions, matrilineal customary law, territorial councils, merchant and overseas networks, and a revived Pagaruyung royal tradition.",canon:"West Sumatra, Bukittinggi, Padang, the Islamic–matrilineal constitutional problem, and cultural influence are established. Whether Pagaruyung is a monarchy or chiefly ceremonial institution remains open.",
    sections:[
      {id:"foundation",title:"A culturally coherent Sumatran state",html:"<p>Language, customary law, historical institutions, mountain geography, and the Padang outlet give Minangkabau enough cohesion and viability for separate statehood.</p>"},
      {id:"constitution",title:"Islam, custom, and Pagaruyung",html:"<p>The state reconciles Islamic authority with matrilineal inheritance and territorial custom. A revived Pagaruyung institution can supply unity without eliminating councils or religious leadership.</p>"},
      {id:"centers",title:"Bukittinggi and Padang",html:"<p>Bukittinggi serves as the political and educational center; Padang is the principal port. Their relationship joins an inland cultural state to inter-island commerce.</p>"},
      {id:"diaspora",title:"Merchants, teachers, and migration",html:"<p>Minangkabau merchants, teachers, civil servants, and religious thinkers work throughout the southern states. Their influence exceeds the country's physical scale and makes migration a major political and economic institution.</p>"},
      {id:"economy",title:"A diversified small economy",html:"<p>Agriculture, trade, education, crafts, services, and Padang shipping support the state. It lacks the oil concentration of the eastern Sumatran lowlands and is less vulnerable to one corporate concession.</p>"},
      {id:"japan",title:"Japanese finance and local institutions",html:"<p>Japanese banks and shipping houses remain important, but Minangkabau councils, merchants, and overseas networks provide alternative channels of capital and information.</p>"},
      {id:"ideas",title:"National and archipelagic ideas",html:"<p>Educated Minangkabau figures are prominent in both state patriotism and the suppressed Indonesian idea. The government permits cultural connection while policing organizations that claim one archipelagic sovereignty.</p>"},
      {id:"position",title:"Position by 1985",html:"<p>Minangkabau is not a strategic giant but is one of the system's principal exporters of administrators, teachers, religious debate, and commercial talent.</p>"}
    ],related:[{href:"tapanuli.html",kicker:"Northern neighbor",label:"Tapanuli"},{href:"sumatran-malay-federation.html",kicker:"Eastern and southern neighbor",label:"Sumatran Malay Federation"},{href:"indonesian-unification-movement.html",kicker:"Contested political current",label:"Indonesian Unification Movement"},{href:"southern-archipelago-council.html",kicker:"Regional institution",label:"Southern Archipelago Council"}],facts:[["Capital","Bukittinggi"],["Principal port","Padang"],["Territory","Western Sumatra"],["Political tradition","Pagaruyung and territorial councils"],["Religious character","Islamic"],["Customary order","Matrilineal inheritance"],["Regional influence","Merchants, teachers, officials, and religious thinkers"],["1985 alignment","GEACPS"]]
  }),

  "sumatran-malay-federation":southernArchipelagoArticle({
    title:"Sumatran Malay Federation",infoboxKicker:"Eastern and southern Sumatran federation",flag:{src:"assets/diagrams/sumatran-four-state-system.svg",alt:"Sumatra's four-state system",caption:"The federation is Sumatra's richest and least nationally coherent state, organized around autonomous sultanates, ports, and corporate districts"},
    lead:"The Sumatran Malay Federation is the loose federation of eastern and southern Sumatran sultanates, provinces, ports, and islands centered economically on Medan and Palembang. It is the most valuable and the most Japanese-corporate-dominated of the four Sumatran states.",canon:"The Deli–Siak–Riau–Jambi–Palembang–Lampung span, loose federal form, Medan and Palembang centers, resource wealth, and severe corporate dependence are established. Federal capital, crown mechanism, exact boundaries, and flag remain open.",
    sections:[
      {id:"formation",title:"A federation of lowlands and ports",html:"<p>Japan joins sultanates, plantation districts, river provinces, eastern ports, and southern lowlands whose economies face the Malacca and Java seas. The result is viable in revenue but weak in shared national identity.</p>"},
      {id:"members",title:"Sultanates and provincial autonomy",html:"<p>Deli, Siak, Riau, Jambi, Palembang, Lampung, and associated islands retain substantial autonomy. No ruler can easily convert the combined oil and plantation economy into centralized power.</p>"},
      {id:"centers",title:"Medan and Palembang",html:"<p>Medan organizes the northern plantation-commercial system; Palembang organizes southern oil, river, and industrial traffic. Their corporate ties to Singapore and Japan are often stronger than their ties to one another.</p>"},
      {id:"economy",title:"Oil, rubber, tin, and shipping",html:"<p>Petroleum, rubber, plantations, tin and related mining, ports, river transport, and the Singapore approaches make the federation one of the richest southern states.</p>"},
      {id:"corporate",title:"Corporate primacy",html:"<p>Japanese banks, oil firms, plantation houses, insurers, shipping companies, and concession authorities dominate the commanding sectors. Competition among provinces further weakens federal attempts at unified bargaining.</p>"},
      {id:"politics",title:"Weakness as a constitutional strategy",html:"<p>Federal weakness is not simply failure. It protects courts and provinces, reassures Japan, and prevents any one national government from commanding a strategic resource bloc.</p>"},
      {id:"resistance",title:"Sovereignty contests",html:"<p>Governments pursue royalties, local procurement, labor rules, national banks, and shared port authority. Companies can respond by shifting investment among Medan, Palembang, Kalimantan, and other resource states.</p>"},
      {id:"position",title:"Position by 1985",html:"<p>The federation is sovereign, wealthy, and structurally dependent. It supplies the clearest Sumatran example of a state whose political institutions cannot operate successfully against the firms financing its export economy.</p>"}
    ],related:[{href:"aceh.html",kicker:"Northern neighbor",label:"Sultanate of Aceh"},{href:"tapanuli.html",kicker:"Highland neighbor",label:"Tapanuli"},{href:"minangkabau.html",kicker:"Western neighbor",label:"Minangkabau"},{href:"singapore.html",kicker:"Commercial center",label:"Singapore"}],facts:[["Federal capital","Open"],["Economic centers","Medan and Palembang"],["Territory","Eastern and southern Sumatran lowlands and associated islands"],["Government","Loose federation of sultanates and provinces"],["Major resources","Oil, rubber, tin, plantations, and ports"],["Strategic position","Approaches to Singapore"],["Corporate dependence","Very high"],["1985 alignment","GEACPS"]]
  }),

  "bornean-state":southernArchipelagoArticle({
    title:"Bornean State",infoboxKicker:"Postwar Bornean national successor",flag:{src:"assets/diagrams/bornean-succession.svg",alt:"Bornean political succession",caption:"The Bornean State replaces Bornean Malaya while Kalimantan remains separately sovereign"},
    lead:"The Bornean State is the autonomy-based country created by the 1977–1979 settlement that ended Bornean Malaya and the Malay–Bornean War. Its nationality is Bornean rather than narrowly Malay, while Sarawak, North Borneo, indigenous districts, Chinese commercial communities, and other regions retain layered self-government.",canon:"The replacement of Bornean Malaya, Bornean national identity, autonomy-based constitution, separate guarantee for Brunei, and Japanese-brokered settlement are established. Formal name, capital, flag, exact internal boundaries, and final federal terminology remain open.",
    sections:[
      {id:"war",title:"Born from the Malay–Bornean War",html:"<p>Charter conflict and armed revolt destroy the claim that a Malay-headed island state can govern Borneo through inherited imperial categories. Japan eventually limits corporate intervention and brokers a new national settlement.</p>"},
      {id:"settlement",title:"The triangular settlement",html:"<p>The 1977–1979 settlement recognizes a Bornean country, restores a separate peninsular Malaya under Thai protection, and preserves Japan as strategic guarantor. It abandons the project of ruling Borneo as the remnant of a lost Malay peninsula.</p>"},
      {id:"nationality",title:"Bornean nationality",html:"<p>Citizenship is territorial and multinational. Malay institutions remain important, but the state no longer defines Iban, other Dayak peoples, Kadazan-Dusun communities, Chinese communities, and regional societies as subjects of a Malay national empire.</p>"},
      {id:"autonomy",title:"Layered territorial autonomy",html:"<p>Sarawak, North Borneo, coastal centers, interior regions, and local peoples retain councils, customary authority, and administrative guarantees. Autonomy is the mechanism that keeps the state together rather than a decorative concession.</p>"},
      {id:"brunei",title:"Brunei's separate guarantee",html:"<p><a href='brunei.html'>Brunei</a> leaves ordinary Bornean control and receives a separately guaranteed position. Its oil and dynasty remain connected to the island economy without making the sultan head of the successor state.</p>"},
      {id:"economy",title:"Resources and corporate corridors",html:"<p>Oil, timber, rubber, minerals, ports, and river systems supply substantial revenue. Japanese firms retain many concessions, but the war discredits the idea that private security may govern whole regions without national oversight.</p>"},
      {id:"security",title:"National security after corporate war",html:"<p>The government builds police and armed services able to protect corridors while limiting corporate forces. Japan guarantees the external settlement and retains strategic access without restoring the old charter order.</p>"},
      {id:"position",title:"Position by 1985",html:"<p>The Bornean State is a young but recognized member of the southern system. Its legitimacy depends on proving that autonomy and territorial citizenship can outlast the imperial category it replaced.</p>"}
    ],related:[{href:"bornean-malaya.html",kicker:"Predecessor state",label:"Bornean Malaya"},{href:"kalimantan-federation.html",kicker:"Island neighbor",label:"Kalimantan Federation"},{href:"malay-bornean-war.html",kicker:"Founding conflict",label:"Malay–Bornean War"},{href:"brunei.html",kicker:"Separately guaranteed neighbor",label:"Brunei"}],facts:[["Established","1977–1979"],["Predecessor","Bornean Malaya"],["Government","Autonomy-based territorial state"],["Nationality","Bornean"],["Internal structure","Layered regional and customary autonomy"],["Brunei","Separately guaranteed"],["Strategic guarantor","Japan"],["Formal name and capital","Open"]]
  }),

  "kalimantan-federation":southernArchipelagoArticle({
    title:"Kalimantan Federation",infoboxKicker:"Southeastern Bornean associated federation",flag:{src:"assets/diagrams/bornean-succession.svg",alt:"Bornean political succession",caption:"Kalimantan remains separate from both Bornean Malaya and its Bornean successor"},
    lead:"The Kalimantan Federation is the sovereign associated state occupying the former Dutch-administered portion of Borneo. Banjar institutions, coastal sultanates, Dayak autonomies, oil and mining districts, and Japanese corporate municipalities are joined under a deliberately federal constitution.",canon:"The former Dutch Bornean territory, federal structure, Banjarmasin as working capital, principal corporate cities, Dayak autonomy, and very high corporate dependence are established. Exact borders, name, capital, and constituent map remain open.",
    sections:[
      {id:"formation",title:"Federation of the Dutch Bornean zone",html:"<p>Japan refuses both one Bornean country and a collection of nonviable interior microstates. The former Dutch zone becomes a federation whose coastal and river centers supply the machinery of government.</p>"},
      {id:"members",title:"Rulers, districts, and autonomies",html:"<p>Banjar institutions, Kutai and other eastern rulers, western Malay sultanates, Dayak territories, oil districts, and corporate municipalities retain different constitutional relationships to the federal center.</p>"},
      {id:"capital",title:"Banjarmasin and the corporate cities",html:"<p>Banjarmasin is the most common working capital. Balikpapan, Samarinda, Tarakan, and Pontianak are major oil, river, port, mining, and corporate centers with political weight beyond ordinary municipalities.</p>"},
      {id:"interior",title:"The autonomous interior",html:"<p>Distance, rivers, language diversity, and administrative cost make interior autonomy unavoidable. Customary authorities and local councils govern extensive districts while the federal state concentrates on corridors and cities.</p>"},
      {id:"economy",title:"Oil, timber, coal, and river transport",html:"<p>Petroleum, timber, coal, mining, river movement, and shipping produce nearly all high-value revenue. This concentration makes the state unusually vulnerable to a small number of Japanese corporate groups.</p>"},
      {id:"corporate",title:"Corporate municipalities",html:"<p>Company towns provide housing, utilities, clinics, schools, police arrangements, and transport. National politicians argue that commercially efficient municipalities cannot become permanent jurisdictions outside federal law.</p>"},
      {id:"borneo",title:"Relations across Borneo",html:"<p>Kalimantan remains separate through the Bornean Malayan crisis and recognizes the later Bornean State. Border peoples, rivers, trade, and company networks cross the constitutional division.</p>"},
      {id:"position",title:"Position by 1985",html:"<p>Kalimantan is sovereign in law and corporately administered in many revenue districts. It is one of the clearest laboratories of the distinction between a national flag and command of the economic ground beneath it.</p>"}
    ],related:[{href:"bornean-state.html",kicker:"Northern and western neighbor",label:"Bornean State"},{href:"bornean-malaya.html",kicker:"Historical neighbor",label:"Bornean Malaya"},{href:"sumatran-malay-federation.html",kicker:"Resource-system comparison",label:"Sumatran Malay Federation"},{href:"southern-archipelago-council.html",kicker:"Regional institution",label:"Southern Archipelago Council"}],facts:[["Capital","Banjarmasin (working)"],["Territory","Former Dutch-administered Borneo"],["Government","Federal associated state"],["Corporate centers","Balikpapan, Samarinda, Tarakan, and Pontianak"],["Internal order","Rulers, districts, municipalities, and Dayak autonomies"],["Major resources","Oil, timber, coal, and mining"],["Corporate dependence","Very high"],["1985 alignment","GEACPS"]]
  }),

  "south-sulawesi":southernArchipelagoArticle({
    title:"South Sulawesi",infoboxKicker:"Bugis–Makassar maritime state",flag:{src:"assets/diagrams/southern-archipelago-states.svg",alt:"Southern Archipelago state system",caption:"South Sulawesi is the locally rooted maritime connector of the fragmented archipelago"},
    lead:"South Sulawesi is the Bugis–Makassar maritime state of the southern and southeastern peninsulas, centered on Makassar. Seafaring, trade, rice, fisheries, copra, shipbuilding, coastal transport, and the older courts of Bone and Gowa give it commercial influence far beyond its borders.",canon:"The southern territory, Makassar capital, maritime role, courts, and internal highland autonomies are established. Formal constitutional title, borders, flag, and court balance remain open.",
    sections:[
      {id:"formation",title:"A maritime southern state",html:"<p>Japan recognizes the historic and commercial distinction of the Bugis–Makassar south rather than placing all Sulawesi under one government. The state is large enough to administer ports and agriculture without commanding the whole island.</p>"},
      {id:"makassar",title:"Makassar",html:"<p>Makassar is capital, commercial port, shipbuilding center, and junction for routes to Java, Borneo, the Moluccas, and the Lesser Sundas.</p>"},
      {id:"courts",title:"Bone, Gowa, and modern government",html:"<p>Older courts retain ceremonial, landed, and regional authority beside ministries, municipalities, merchant associations, and maritime services. Their balance prevents one dynasty from defining the whole state.</p>"},
      {id:"autonomy",title:"Highland autonomies",html:"<p>Toraja and other highland districts retain substantial cultural and local government guarantees. The arrangement recognizes that the coastal maritime identity is not the island's only political tradition.</p>"},
      {id:"economy",title:"Rice, copra, fisheries, and shipbuilding",html:"<p>Agriculture and fisheries support the population while shipbuilding, coastal transport, and merchant networks provide regional reach. Japanese firms dominate larger finance and machinery but depend on local sailors and traders.</p>"},
      {id:"diaspora",title:"The maritime diaspora",html:"<p>Bugis and Makassar merchants and crews work across the southern Sphere. Their networks reconnect fragmented states socially and commercially without creating one Indonesian government.</p>"},
      {id:"politics",title:"The commercial-unity question",html:"<p>Japan values locally rooted maritime skill but watches any institution that could become an independent archipelagic merchant marine. South Sulawesi defends mobility as commerce rather than concealed federation.</p>"},
      {id:"position",title:"Position by 1985",html:"<p>The state is a medium power whose influence rests on people and routes more than strategic industry. It is the southern system's principal non-Japanese maritime intermediary.</p>"}
    ],related:[{href:"north-sulawesi.html",kicker:"Northern island neighbor",label:"North Sulawesi"},{href:"east-java-madura.html",kicker:"Western maritime partner",label:"East Java and Madura"},{href:"moluccan-federation.html",kicker:"Eastern maritime partner",label:"Moluccan Federation"},{href:"southern-archipelago-council.html",kicker:"Regional institution",label:"Southern Archipelago Council"}],facts:[["Capital","Makassar"],["Territory","Southern and southeastern Sulawesi"],["Principal peoples","Bugis and Makassar communities"],["Historic courts","Bone and Gowa"],["Internal autonomy","Toraja and other highland regions"],["Economic strengths","Rice, fisheries, copra, shipbuilding, and trade"],["Regional role","Locally rooted maritime partner"],["1985 alignment","GEACPS"]]
  }),

  "north-sulawesi":southernArchipelagoArticle({
    title:"North Sulawesi",infoboxKicker:"Northern Sulawesi maritime federation",flag:{src:"assets/diagrams/southern-archipelago-states.svg",alt:"Southern Archipelago state system",caption:"North Sulawesi balances Christian Minahasa, Muslim Gorontalo, island communities, and Japanese strategic bases"},
    lead:"North Sulawesi is the federal state of Minahasa, Gorontalo, the northern peninsula, and nearby island chains. Manado and Gorontalo anchor a politically delicate but highly literate naval-frontier society.",canon:"The northern territory, Manado capital, Gorontalo secondary center, Christian–Muslim balance, high literacy, and Japanese naval value are established. Federal title, island boundaries, flag, and representation remain open.",
    sections:[
      {id:"formation",title:"A northern maritime federation",html:"<p>Japan separates the northern peninsula from Bugis–Makassar South Sulawesi and joins it to nearby islands whose shipping, education, and strategic geography face the Philippine and Moluccan seas.</p>"},
      {id:"centers",title:"Manado and Gorontalo",html:"<p>Manado is capital and principal administrative center. Gorontalo retains major political, religious, and commercial weight, preventing Minahasa from defining the entire country.</p>"},
      {id:"religion",title:"Christian and Muslim regions",html:"<p>Minahasa is heavily Christian and institutionally connected to schools and churches; Gorontalo is strongly Muslim. Federal government treats religious balance as a constitutional foundation.</p>"},
      {id:"islands",title:"The island chains",html:"<p>Northern island communities depend on fishing, shipping, local councils, and Japanese naval and aviation routes. Distance gives them claims to autonomy beyond ordinary provincial government.</p>"},
      {id:"economy",title:"Plantations, fishing, and services",html:"<p>Copra, plantations, fisheries, shipping, education, and base services sustain the economy. The state lacks the extractive wealth of Kalimantan but possesses skilled administration.</p>"},
      {id:"strategy",title:"Japanese naval frontier",html:"<p>Airfields, ports, surveillance, and sea-lane access make North Sulawesi strategically reliable. Japanese guarantees strengthen the country while limiting independent control of the most important installations.</p>"},
      {id:"education",title:"Literacy and administrative capacity",html:"<p>Mission-era and later national schools produce a high concentration of teachers, clerks, officers, and technical personnel. This capacity gives the small state influence within regional councils.</p>"},
      {id:"position",title:"Position by 1985",html:"<p>North Sulawesi is a stable but delicate federation. Its national legitimacy rests on preventing the naval alliance and educated Minahasan institutions from marginalizing Gorontalo and the islands.</p>"}
    ],related:[{href:"south-sulawesi.html",kicker:"Southern island neighbor",label:"South Sulawesi"},{href:"moluccan-federation.html",kicker:"Eastern maritime neighbor",label:"Moluccan Federation"},{href:"philippines.html",kicker:"Northern sea-lane partner",label:"Philippine Republic"},{href:"southern-archipelago-council.html",kicker:"Regional institution",label:"Southern Archipelago Council"}],facts:[["Capital","Manado"],["Secondary center","Gorontalo"],["Territory","Northern Sulawesi and nearby island chains"],["Government","Federal associated state"],["Religious balance","Christian Minahasa and Muslim Gorontalo"],["Economic strengths","Fisheries, plantations, education, and base services"],["Strategic role","Japanese naval and aviation frontier"],["1985 alignment","GEACPS"]]
  }),

  "bali":southernArchipelagoArticle({
    title:"Bali",infoboxKicker:"Hindu court and temple federation",flag:{src:"assets/diagrams/southern-archipelago-states.svg",alt:"Southern Archipelago state system",caption:"Bali is the clearest religious-cultural state in the southern settlement"},
    lead:"Bali is the Hindu associated state centered on Denpasar and organized through retained royal houses, temples, villages, and irrigation institutions. Japan presents the country as proof that the Co-Prosperity Sphere preserves distinct Asian civilizations, while tourism and heritage corporations turn preservation itself into an economic dispute.",canon:"The Balinese territory, Denpasar capital, royal federation, Hindu public identity, cultural-protection role, and later tourism conflict are established. Formal crown structure, flag, and associated islands remain open.",
    sections:[
      {id:"formation",title:"A religious-cultural state",html:"<p>Bali's island geography, Hindu institutions, courts, and village order justify sovereignty separate from Muslim Lombok and the Javanese states.</p>"},
      {id:"government",title:"Royal houses and national administration",html:"<p>Retained or restored royal houses form a federation around a modern government at Denpasar. Court authority coexists with elected or appointed councils, ministries, and village institutions.</p>"},
      {id:"temple",title:"Temple, village, and irrigation",html:"<p>Temples, ritual calendars, customary villages, and irrigation associations organize land, labor, worship, and community identity. State law protects them as public institutions rather than private folklore.</p>"},
      {id:"economy",title:"Agriculture, crafts, and transport",html:"<p>Agriculture, crafts, food, local trade, transport, and later tourism sustain the economy. Japan supplies shipping, credit, infrastructure, and the largest external visitor market.</p>"},
      {id:"preservation",title:"The preservation showcase",html:"<p>Japanese officials use Bali to demonstrate imperial respect for civilizational difference. Balinese leaders accept protection while rejecting the claim that survival requires permanent foreign management.</p>"},
      {id:"tourism",title:"Tourism and the sale of heritage",html:"<p>Hotels, airlines, packaged festivals, crafts markets, and cultural districts make heritage a major corporate sector. Disputes ask whether companies preserve living culture or reorganize it for foreign consumption.</p>"},
      {id:"neighbors",title:"Relations with Lombok and Java",html:"<p>Bali trades intensively with Lombok–Sumbawa and East Java while guarding religious and political separation. Regional travel does not imply a common nationality.</p>"},
      {id:"position",title:"Position by 1985",html:"<p>Bali is culturally prominent, strategically secondary, and economically dependent on access. Its autonomy is real, but the preservation economy gives Japanese firms unusual power over how the nation is represented.</p>"}
    ],related:[{href:"lombok-sumbawa.html",kicker:"Eastern neighbor",label:"Lombok–Sumbawa"},{href:"east-java-madura.html",kicker:"Western maritime neighbor",label:"East Java and Madura"},{href:"southern-archipelago-council.html",kicker:"Regional institution",label:"Southern Archipelago Council"},{href:"japanese-preservationism.html",kicker:"Imperial cultural policy",label:"Japanese Preservationism"}],facts:[["Capital","Denpasar"],["Territory","Bali and immediately associated islands"],["Government","Federation of royal houses"],["Public religion","Hinduism"],["Core institutions","Courts, temples, villages, and irrigation associations"],["Economic strengths","Agriculture, crafts, tourism, and transport"],["Imperial role","Cultural-preservation showcase"],["1985 alignment","GEACPS"]]
  }),

  "lombok-sumbawa":southernArchipelagoArticle({
    title:"Lombok–Sumbawa",infoboxKicker:"Western Lesser Sunda federation",flag:{src:"assets/diagrams/southern-archipelago-states.svg",alt:"Southern Archipelago state system",caption:"Religion and island geography separate Lombok–Sumbawa from Bali and the eastern federation"},
    lead:"Lombok–Sumbawa is the Muslim federation of Lombok, Sumbawa, and nearby western Lesser Sunda islands. Its royal houses and island administrations govern a small but coherent country based on agriculture, livestock, fisheries, shipping, mining, and Japanese development concessions.",canon:"The western Lesser Sunda territory, federal Muslim character, separate status from Bali and the eastern islands, and economic basis are established. Capital, formal name, flag, and constituent list remain open.",
    sections:[
      {id:"formation",title:"Separation from Bali and the east",html:"<p>Island geography and religion reinforce a political boundary between Hindu Bali, Muslim Lombok–Sumbawa, and the more heavily Christian eastern federation.</p>"},
      {id:"federation",title:"Island administrations and royal houses",html:"<p>Local rulers and island governments retain extensive authority beneath a federal cabinet. The system avoids both domination by Lombok and administrative fragmentation into tiny sovereign islands.</p>"},
      {id:"capital",title:"The capital question",html:"<p>Cakranegara or another Lombok administrative center is the leading working candidate for capital. The choice remains sensitive because Sumbawa must not become a remote dependency.</p>"},
      {id:"economy",title:"Livestock, rice, fisheries, and mining",html:"<p>Livestock, rice, fisheries, local mining, and inter-island shipping provide the base. Drought, transport cost, and uneven development make Japanese concession finance unusually important.</p>"},
      {id:"development",title:"Development concessions",html:"<p>Roads, ports, water systems, mines, and shipping contracts are commonly built under Japanese or mixed concessions. Governments bargain for local hiring and revenue without possessing many alternative financiers.</p>"},
      {id:"religion",title:"Muslim public identity",html:"<p>Islam supplies common public language across different islands and houses without erasing local custom. Religious institutions also mediate labor migration and development disputes.</p>"},
      {id:"neighbors",title:"The Lesser Sunda corridor",html:"<p>The state sits between Bali and the Eastern Lesser Sunda Federation. Shipping, weather, disease control, migration, and rescue therefore require unusually close council coordination.</p>"},
      {id:"position",title:"Position by 1985",html:"<p>Lombok–Sumbawa is small but administratively viable. It remains dependent on access and capital while avoiding incorporation into culturally stronger neighbors.</p>"}
    ],related:[{href:"bali.html",kicker:"Western neighbor",label:"Bali"},{href:"eastern-lesser-sunda-federation.html",kicker:"Eastern neighbor",label:"Eastern Lesser Sunda Federation"},{href:"southern-archipelago-council.html",kicker:"Regional institution",label:"Southern Archipelago Council"},{href:"japanese-east-indies.html",kicker:"Administrative predecessor",label:"Japanese East Indies"}],facts:[["Capital","Open; Cakranegara commonly proposed"],["Territory","Lombok, Sumbawa, and nearby western Lesser Sunda islands"],["Government","Federation of island administrations and royal houses"],["Public religion","Islam"],["Economic strengths","Livestock, rice, fisheries, mining, and shipping"],["Principal development partner","Japan"],["Regional position","Between Bali and the Eastern Lesser Sundas"],["1985 alignment","GEACPS"]]
  }),

  "eastern-lesser-sunda-federation":southernArchipelagoArticle({
    title:"Eastern Lesser Sunda Federation",infoboxKicker:"Christian and customary island federation",flag:{src:"assets/diagrams/southern-archipelago-states.svg",alt:"Southern Archipelago state system",caption:"Kupang coordinates a dispersed federation of Christian, customary, and locally governed islands"},
    lead:"The Eastern Lesser Sunda Federation is the island state of Flores, Sumba, western Timor, Rote, Savu, Alor, and related islands, centered on Kupang. Catholic, Protestant, customary, royal, and local-council institutions govern a country whose unity is administrative and maritime rather than ethnic.",canon:"The general island membership, Kupang capital, Christian and customary federal character, exclusion of Portuguese Timor, and strategic-economic role are established. Exact constituent list, title, flag, and Portuguese frontier remain open.",
    sections:[
      {id:"formation",title:"A federation of the eastern islands",html:"<p>Japan converts the colonial Great East's smaller island administrations into one viable state rather than granting sovereignty to each island or attaching them to Bali or the Moluccas.</p>"},
      {id:"members",title:"Flores, Sumba, Timor, and the smaller islands",html:"<p>Flores, Sumba, western Timor, Rote, Savu, Alor, and neighboring islands retain distinct councils, rulers, churches, and customary law within the federation.</p>"},
      {id:"kupang",title:"Kupang",html:"<p>Kupang is capital, port, military-air center, and administrative junction. Its dominance is practical rather than proof of one Timorese national identity.</p>"},
      {id:"religion",title:"Catholic, Protestant, and customary institutions",html:"<p>Churches supply schools, clinics, records, and trans-island networks. Customary councils and local rulers retain authority over land, family, and communal obligations.</p>"},
      {id:"economy",title:"Livestock, agriculture, shipping, and airfields",html:"<p>Livestock, agriculture, fisheries, small ports, military airfields, and shipping concessions sustain a relatively poor and strategically located federation.</p>"},
      {id:"portuguese",title:"Portuguese Timor",html:"<p>Portuguese Timor remains outside the federation. Its status depends on Japan's diplomacy with Portugal and the Latin Bloc rather than the former Dutch East Indian settlement.</p>"},
      {id:"dependence",title:"Corporate and logistical dependence",html:"<p>Thin markets and dispersed islands give shipping, communications, aviation, and development contractors great influence. Local government can regulate communities more easily than it can replace a transport concession.</p>"},
      {id:"position",title:"Position by 1985",html:"<p>The federation is sovereign but among the system's most dependent members. Its survival demonstrates why common weather, rescue, health, and shipping institutions are indispensable without requiring political union.</p>"}
    ],related:[{href:"lombok-sumbawa.html",kicker:"Western neighbor",label:"Lombok–Sumbawa"},{href:"moluccan-federation.html",kicker:"Eastern neighbor",label:"Moluccan Federation"},{href:"southern-archipelago-council.html",kicker:"Essential common institution",label:"Southern Archipelago Council"},{href:"portugal.html",kicker:"Portuguese Timor connection",label:"Portugal"}],facts:[["Capital","Kupang"],["Principal islands","Flores, Sumba, western Timor, Rote, Savu, and Alor"],["Government","Federal island state"],["Religious order","Catholic, Protestant, and customary pluralism"],["Portuguese Timor","Outside the federation"],["Economic strengths","Livestock, agriculture, shipping, and base services"],["Corporate dependence","High"],["1985 alignment","GEACPS"]]
  }),

  "moluccan-federation":southernArchipelagoArticle({
    title:"Moluccan Federation",infoboxKicker:"Northern and southern Moluccan federation",flag:{src:"assets/diagrams/southern-archipelago-states.svg",alt:"Southern Archipelago state system",caption:"Ternate and Ambon anchor a dual federation of Muslim northern and Christian southern islands"},
    lead:"The Moluccan Federation is the dual-centered state of Ternate, Tidore, Ambon, Banda, and the surrounding northern and southern islands. Muslim sultanates in the north, a heavily Christian administrative society in the south, and local island councils share government beneath Japanese maritime security.",canon:"The broad Moluccan territory, Ternate–Ambon dual structure, religious balance, local councils, economy, and Japanese security role are established. Capital formula, flag, exact islands, and federal apportionment remain open.",
    sections:[
      {id:"formation",title:"One federation rather than many islands",html:"<p>The Moluccas are too small and economically interdependent for many sovereign microstates but too divided for a unitary country. Japan therefore constructs a federation with explicit northern and southern poles.</p>"},
      {id:"north",title:"Ternate, Tidore, and the Muslim north",html:"<p>Ternate or Tidore represents the northern sultanates and Muslim communities. Royal, religious, and maritime institutions retain constitutional standing.</p>"},
      {id:"south",title:"Ambon and the Christian south",html:"<p>Ambon is the principal southern administrative and educational center. Christian institutions and a trained administrative class give it influence that northern governments repeatedly fear is excessive.</p>"},
      {id:"islands",title:"Island councils",html:"<p>Banda and smaller islands retain local councils, rulers, and land arrangements. Federal authority concentrates on shipping, taxation, security, and inter-island services.</p>"},
      {id:"economy",title:"Spices, fisheries, forestry, and naval supply",html:"<p>Spices, fisheries, forestry, small plantations, shipping, and naval supply provide revenue. Dependence on a limited number of routes and buyers gives Japanese companies exceptional leverage.</p>"},
      {id:"security",title:"Japanese maritime security",html:"<p>Japan controls the principal naval and inter-island security system. National patrol and police services operate locally while strategic bases and sea-lane defense remain under Japanese guarantee.</p>"},
      {id:"politics",title:"The permanent balance dispute",html:"<p>Politics turns repeatedly on whether the northern sultanates or the Ambonese administrative class possess too much influence. The federal structure treats imbalance as a normal constitutional problem rather than evidence that the state should divide.</p>"},
      {id:"position",title:"Position by 1985",html:"<p>The federation is one of the most corporately and strategically dependent southern states. Its real achievement is preserving a shared government without requiring either religious region to accept the other's national supremacy.</p>"}
    ],related:[{href:"north-sulawesi.html",kicker:"Western maritime neighbor",label:"North Sulawesi"},{href:"eastern-lesser-sunda-federation.html",kicker:"Southern neighbor",label:"Eastern Lesser Sunda Federation"},{href:"southern-archipelago-council.html",kicker:"Regional institution",label:"Southern Archipelago Council"},{href:"japanese-pacific-territories.html",kicker:"Strategic maritime system",label:"Japanese Pacific Territories"}],facts:[["Political centers","Ternate and Ambon"],["Territory","Northern and southern Moluccas"],["Government","Dual federal state"],["Northern institutions","Muslim sultanates"],["Southern institutions","Christian Ambonese administration"],["Economic strengths","Spices, fisheries, forestry, shipping, and naval supply"],["Strategic guarantor","Japan"],["1985 alignment","GEACPS"]]
  }),

  "bornean-malaya":southernArchipelagoArticle({
    title:"Bornean Malaya",category:"Former countries",eyebrow:"Former associated state · 1947–1979",infoboxKicker:"Malay-headed Bornean state",flag:{src:"assets/diagrams/bornean-succession.svg",alt:"Bornean political succession",caption:"Bornean Malaya was an original Southern Archipelago state and the predecessor of the Bornean State"},
    lead:"Bornean Malaya was the Malay-headed associated state formed from Brunei, Sarawak, North Borneo, Labuan, and neighboring islands after Thailand absorbed the Malayan peninsula and Singapore remained independent. Its attempt to preserve Malay national institutions over a multinational Bornean empire ended in charter crisis, revolt, war, and replacement by the Bornean State.",canon:"The initial territory, Brunei ceremonial headship, Kuching's working administrative role, multinational imperial character, corporate-security crisis, 1974–1976 war, and 1977–1979 replacement are established. Formal title, flag, exact constitution, and leaders remain open.",
    sections:[
      {id:"formation",title:"The surviving Malay national state",html:"<p>With the peninsula under Thailand and Singapore separate, Bornean Malaya becomes the institutional refuge of Malay royal and national identity. It claims liberation from Britain while governing territories never reducible to one Malay nation.</p>"},
      {id:"territory",title:"Brunei, Sarawak, and North Borneo",html:"<p>The state includes Brunei, Sarawak, North Borneo, Labuan, and associated islands. Brunei is the ceremonial center; Kuching is the leading working administrative and commercial center; Jesselton is an important secondary port.</p>"},
      {id:"empire",title:"A national title over a multinational empire",html:"<p>Iban and other Dayak peoples, Kadazan-Dusun districts, Chinese communities, regional societies, and coastal authorities receive autonomy but remain beneath a Malay-headed state whose lost national homeland lies across the sea.</p>"},
      {id:"economy",title:"Oil, timber, shipping, and concessions",html:"<p>Oil, timber, rubber, ports, and shipping make the state valuable. Japanese companies control essential corridors and increasingly treat charter rights as authority over labor, policing, land, and local government.</p>"},
      {id:"grievance",title:"The lost peninsula",html:"<p>Commemoration of the Malayan peninsula is permitted, but serious irredentism against Thailand is not. The gap between national mythology and strategic reality weakens the government's legitimacy in Borneo.</p>"},
      {id:"crisis",title:"Charter crisis and revolt",html:"<p>Attempts to preserve or extend corporate and Malay political privileges produce constitutional breakdown after 1973. Bornean opposition develops a territorial national claim distinct from both Indonesian unity and Malay restoration.</p>"},
      {id:"war",title:"The Malay–Bornean War",html:"<p>Armed conflict from 1974 to 1976 and the wider strategic crisis expose the danger of corporate security forces, ethnic imperial government, and Thai–Japanese disagreement.</p>"},
      {id:"dissolution",title:"Dissolution and succession",html:"<p>The 1977–1979 triangular settlement replaces Bornean Malaya with the <a href='bornean-state.html'>Bornean State</a>, separately guarantees Brunei, and restores a peninsular Malayan monarchy under Thai protection.</p>"}
    ],related:[{href:"bornean-state.html",kicker:"Successor",label:"Bornean State"},{href:"malay-bornean-war.html",kicker:"Dissolution conflict",label:"Malay–Bornean War"},{href:"malaya.html",kicker:"Peninsular successor",label:"Federated Kingdom of Malaya"},{href:"brunei.html",kicker:"Former ceremonial center",label:"Brunei"}],facts:[["Established","c. 1947"],["Dissolved","1977–1979"],["Territory","Brunei, Sarawak, North Borneo, Labuan, and associated islands"],["Ceremonial center","Brunei"],["Administrative center","Kuching (working)"],["Political character","Malay-headed multinational empire"],["Dissolution conflict","Malay–Bornean War"],["Successor","Bornean State"]]
  }),

  "southern-archipelago-council":southernArchipelagoArticle({
    title:"Southern Archipelago Council",category:"International organizations",eyebrow:"Interstate technical council · Southern Archipelago",infoboxKicker:"Common machinery without federation",flag:{src:"assets/diagrams/southern-archipelago-council.svg",alt:"Functions and limits of the Southern Archipelago Council",caption:"The Council coordinates shared systems but possesses none of the sovereign powers of a federation"},
    lead:"The Southern Archipelago Council is the technical coordinating body through which the fifteen successor states manage shipping, customs documents, disease control, weather, fisheries, communications, labor movement, piracy, and rescue without forming an Indonesian federation.",canon:"The need for and general design of the Council are established working canon. Formal treaty title, founding date, headquarters, voting rules, committees, and secretaries remain open.",
    sections:[
      {id:"creation",title:"Created by practical interdependence",html:"<p>Fragmentation does not remove shared seas, storms, diseases, shipping routes, fish stocks, labor migration, or technical systems. Japan and the associated states therefore require an institution that can coordinate without becoming a national government.</p>"},
      {id:"functions",title:"Technical functions",html:"<p>The Council standardizes shipping lanes, customs documents, postal and radio procedures, fisheries rules, weather and disaster warnings, disease control, search and rescue, piracy suppression, and selected labor arrangements.</p>"},
      {id:"limits",title:"What the Council cannot do",html:"<p>It has no common citizenship, army, taxing power, independent foreign policy, parliamentary authority, or power to override national law. Agreements take effect through the statutes and ministries of each member.</p>"},
      {id:"japan",title:"Japanese strategic chairmanship",html:"<p>Japan chairs or dominates strategic committees involving defense, sea lanes, standards, communications, and major corporate disputes. The arrangement secures imperial requirements without creating a Japanese colonial governor.</p>"},
      {id:"singapore",title:"Singaporean administrative support",html:"<p>Singapore supplies finance, shipping data, insurance, clerical expertise, and meeting infrastructure. Its influence is commercial rather than a claim to rule the islands.</p>"},
      {id:"states",title:"National implementation",html:"<p>Each member sends ministers, officials, specialists, and corporate advisers. A common rule remains effective only when national customs, ports, police, courts, and ministries implement it.</p>"},
      {id:"indonesia",title:"The anti-federal safeguard",html:"<p>Official design prevents the Council from acquiring popular representation or an autonomous budget large enough to become a parliament. Unificationists treat that safeguard as proof that Japan fears any functioning common institution.</p>"},
      {id:"position",title:"Position by 1985",html:"<p>The Council makes the archipelago work as an economic and logistical area while preserving fifteen foreign policies and citizenship systems. Its very effectiveness explains why neither Japan nor most member governments see political federation as necessary.</p>"}
    ],related:[{href:"east-indies-successor-states.html",kicker:"Member system",label:"Southern Archipelago States"},{href:"singapore.html",kicker:"Administrative and financial support",label:"Singapore"},{href:"indonesian-unification-movement.html",kicker:"Federal alternative",label:"Indonesian Unification Movement"},{href:"geacps.html",kicker:"Wider international order",label:"Greater East Asia Co-Prosperity Sphere"}],facts:[["Organization type","Interstate technical council"],["Members","Fifteen Southern Archipelago states"],["Strategic chair","Japan"],["Administrative support","Singapore"],["Core functions","Shipping, customs, health, weather, fisheries, communications, and rescue"],["Common citizenship","None"],["Taxing and military power","None"],["Formal title and founding date","Open"]]
  }),

  "japanese-east-indies":southernArchipelagoArticle({
    title:"Japanese East Indies",category:"Former administrations",eyebrow:"Military and resource administration · 1942–1947",infoboxKicker:"Predecessor of the Southern Archipelago states",flag:{src:"assets/diagrams/southern-archipelago-states.svg",alt:"Successor system of the Japanese East Indies",caption:"Three wartime administrative zones become the foundation for fifteen postwar states"},
    lead:"The Japanese East Indies was the wartime military, naval, and resource administration that replaced Dutch rule between 1942 and 1947. It governed Sumatra, Java and Madura, and Borneo and the eastern islands through separate commands while transferring the colonial economy's commanding assets to Japanese custodians and corporate operators.",canon:"The three-zone structure, resource mission, seizure or custodianship of European assets, immediate zaibatsu entry, and transformation into the postwar state system are established. Exact command boundaries, officials, company allocations, and transfer instruments remain open.",
    sections:[
      {id:"conquest",title:"Conquest and administrative division",html:"<p>Japanese forces remove Dutch authority but do not establish one Indonesian government. Sumatra falls under one army administration, Java and Madura under another, and Borneo and the eastern islands under naval authority.</p>"},
      {id:"mission",title:"Resource and logistics mission",html:"<p>Oil, rubber, tin, food, shipping, ports, airfields, warehouses, and labor dominate policy. The administration treats the archipelago as several strategic production zones connected to Japan's war economy.</p>"},
      {id:"assets",title:"Custody of the colonial economy",html:"<p>Dutch plantations, oil companies, mines, banks, shipping lines, railways, utilities, ports, warehouses, and European commercial property are seized or placed under Japanese custodianship.</p>"},
      {id:"zaibatsu",title:"Immediate corporate entry",html:"<p>Zaibatsu and national-policy firms enter because military commands cannot themselves operate the entire productive system. Corporate control therefore predates the sovereignty of every successor government.</p>"},
      {id:"local",title:"Local institutions and mobilization",html:"<p>Japanese authorities use courts, sultanates, municipal bodies, religious networks, nationalist cadres, police, and labor organizations differently by region. These institutions later become building blocks for separate countries.</p>"},
      {id:"nationalists",title:"Use and containment of nationalists",html:"<p>Sukarno, Hatta, and other anti-Dutch leaders can mobilize labor and legitimacy, but any claim to one archipelagic republic conflicts with the separate commands and corporate concessions.</p>"},
      {id:"transition",title:"Sovereignty after concession",html:"<p>From 1947 the commands transfer territory to courts, councils, ministries, police, and small armies. Independence treaties preserve Japanese banks, management contracts, shipping rights, debts, and standards already in force.</p>"},
      {id:"legacy",title:"Administrative legacy",html:"<p>The wartime zones make permanent fragmentation appear as institutional continuity rather than a postwar partition imposed on an existing state. The Japanese East Indies disappears, but its asset map and command geography survive in the fifteen-country order.</p>"}
    ],related:[{href:"east-indies-successor-states.html",kicker:"Successor system",label:"Southern Archipelago States"},{href:"indonesian-unification-movement.html",kicker:"Suppressed alternative",label:"Indonesian Unification Movement"},{href:"greater-east-asia-economic-board.html",kicker:"Postwar planning institution",label:"Greater East Asia Economic Board"},{href:"japan.html",kicker:"Governing power",label:"Empire of Japan"}],facts:[["Period","1942–1947"],["Predecessor","Dutch East Indies"],["Major zones","Sumatra; Java and Madura; Borneo and eastern islands"],["Principal mission","Resource extraction and logistics"],["Asset policy","Seizure or custodianship of European enterprises"],["Corporate operators","Japanese zaibatsu and policy companies"],["Political successor","Fifteen Southern Archipelago states"],["Unified Indonesian government","Never established"]]
  }),

  "indonesian-unification-movement":southernArchipelagoArticle({
    title:"Indonesian Unification Movement",category:"Political movements",eyebrow:"Pan-archipelagic nationalism · suppressed after 1947",infoboxKicker:"Opposition to the fifteen-state settlement",flag:{src:"assets/diagrams/southern-archipelago-states.svg",alt:"The state system opposed by Indonesian unificationists",caption:"Unificationists interpret fifteen associated states as the partition of a country; governments interpret Indonesia as a centralist project"},
    lead:"The Indonesian unification movement is the family of political, cultural, student, labor, exile, and clandestine organizations that regard the former Dutch East Indies as one nation and reject the Southern Archipelago settlement. Indonesia survives as their name for a country that never receives a recognized government.",canon:"The survival of Indonesian identity, official rejection of a unified republic, continued Malay-derived lingua franca, and structural suppression of a pan-Indonesian government are established. Sukarno's and Hatta's final offices, exiles, detentions, and later organizations remain open.",
    sections:[
      {id:"origins",title:"Nationalism before Japanese victory",html:"<p>Late colonial organizations, shared anti-Dutch politics, Malay-language print, urban networks, and nationalist leadership already support an Indonesian political idea before 1942.</p>"},
      {id:"occupation",title:"Mobilization under Japan",html:"<p>Japanese authorities initially use nationalist leaders to mobilize labor, denounce Dutch rule, and create local institutions. Those same networks become dangerous once Tokyo chooses separate sovereign states.</p>"},
      {id:"leaders",title:"Sukarno and Hatta",html:"<p>Sukarno and Hatta are offered plausible regional, cultural, or economic roles but cannot retain an unrestricted mass organization demanding one republic. Their exact later biographies remain disputed and open.</p>"},
      {id:"suppression",title:"Suppression of a common government",html:"<p>Unity declarations, national committees, armed organizations, and institutions claiming archipelagic sovereignty are isolated, divided, absorbed into regional politics, exiled, detained, or denied legal recognition.</p>"},
      {id:"language",title:"Malay and the language of Indonesia",html:"<p>A Malay-derived inter-island language survives in ports, trade, popular media, and opposition politics. It never becomes the compulsory national language of the entire archipelago; state languages and Japanese technical usage remain institutionally stronger.</p>"},
      {id:"arguments",title:"Two interpretations of partition",html:"<p>Unificationists describe fifteen governments as the partition of a country for corporate advantage. State patriots describe Indonesia as a Javanese-centered project that would subordinate Acehnese, Sundanese, Balinese, Moluccan, and other nations.</p>"},
      {id:"networks",title:"Exile and legal-cultural networks",html:"<p>Students, writers, port workers, merchants, religious figures, migrants, and expatriates preserve common symbols and debates. Legal cultural activity frequently overlaps with organizations suspected of political federation.</p>"},
      {id:"position",title:"Position by 1985",html:"<p>No pan-Indonesian government exists and no member state endorses immediate union. Indonesia remains a meaningful dissenting nationality whose lack of sovereign institutions is itself the central fact of the movement.</p>"}
    ],related:[{href:"east-indies-successor-states.html",kicker:"State system opposed",label:"Southern Archipelago States"},{href:"japanese-east-indies.html",kicker:"Formative administration",label:"Japanese East Indies"},{href:"southern-archipelago-council.html",kicker:"Non-federal common institution",label:"Southern Archipelago Council"},{href:"sunda.html",kicker:"Largest western Javanese state",label:"Sunda"}],facts:[["Political objective","One sovereign Indonesian state"],["Recognized national government","None"],["Principal early leaders","Sukarno and Mohammad Hatta"],["Institutional status","Suppressed, divided, exiled, or cultural"],["Common language","Malay-derived inter-island lingua franca"],["Official collective term","Southern Archipelago, not Indonesia"],["Principal opponents","Member governments and Japan"],["1985 status","Persistent opposition idea"]]
  })
});

